/**
 * Check if a referenceLibraryId represents a public emission factor.
 *
 * @param referenceLibraryId - The ID to check
 * @returns true if public (not in internal list), false if internal or null
 */
export function isPublicEF(referenceLibraryId: number | null): boolean {
  if (referenceLibraryId === null) return false;
  return !INTERNAL_EF_IDS.has(referenceLibraryId);
}
